const rawInput = $input.first()?.json || {};
let rawAgent5Json = rawInput.agent5_json ?? rawInput['Agent 5 JSON 结果'] ?? rawInput.data ?? rawInput.json ?? '';

// 支持用户直接粘贴 JSON、对象、数组或 Markdown JSON 代码块。
function stripMarkdownFence(value) {
  const textValue = typeof value === 'string' ? value.trim() : value;
  if (typeof textValue !== 'string') return textValue;
  return textValue.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}

function parseJsonLike(value) {
  const unfenced = stripMarkdownFence(value);
  if (typeof unfenced === 'string') return JSON.parse(unfenced);
  return unfenced;
}

// Agent 5 V1.1 真实输出常见形态：[{ voiceover_packages: [...] }]。
// 这里必须读取内部 voiceover_packages，而不是误把外层包装数组当作包列表。
function findPackages(value) {
  if (Array.isArray(value)) {
    const nested = [];
    for (const item of value) {
      if (item && typeof item === 'object') {
        const inner = findPackages(item);
        if (inner.length > 0) nested.push(...inner);
      }
    }
    return nested.length > 0 ? nested : value;
  }
  if (!value || typeof value !== 'object') return [];
  const possibleKeys = ['voiceover_packages', 'voiceoverPackages', 'subtitle_packages', 'publishing_inputs', 'packages', 'results', 'records'];
  for (const key of possibleKeys) {
    if (Array.isArray(value[key])) return value[key];
  }
  return [value];
}

function text(value) { return String(value ?? '').trim(); }
function normalizePackage(pkg, index) {
  const narrationSegments = Array.isArray(pkg.narration_segments) ? pkg.narration_segments : (Array.isArray(pkg.voiceover_segments) ? pkg.voiceover_segments : []);
  const subtitleSegments = Array.isArray(pkg.subtitle_segments) ? pkg.subtitle_segments : (Array.isArray(pkg.subtitles) ? pkg.subtitles : []);
  return {
    ...pkg,
    package_id: text(pkg.package_id || pkg.voiceover_id || pkg.id || `agent5_package_${index + 1}`),
    video_title: text(pkg.video_title || pkg.title || pkg.topic || pkg.source_title || `Untitled Package ${index + 1}`),
    full_voiceover_script: text(pkg.full_voiceover_script || pkg.voiceover_script || pkg.voiceover || pkg.script || ''),
    voiceover_script: text(pkg.voiceover_script || pkg.full_voiceover_script || pkg.voiceover || pkg.script || ''),
    narration_segments: narrationSegments,
    subtitle_segments: subtitleSegments,
    srt: text(pkg.srt || ''),
    tts_prompt: text(pkg.tts_prompt || ''),
    pacing_notes: text(pkg.pacing_notes || ''),
    hashtags: Array.isArray(pkg.hashtags) ? pkg.hashtags : [],
    ready_for_agent6: pkg.ready_for_agent6,
    source_index: index + 1,
  };
}

try {
  const parsed = parseJsonLike(rawAgent5Json);
  const voiceover_packages = findPackages(parsed).map(normalizePackage).filter((pkg) => pkg.video_title);
  return [{ json: { status: 'parsed', parse_error: '', source_agent: 'agent_5', voiceover_packages, total_voiceover_packages: voiceover_packages.length } }];
} catch (error) {
  return [{ json: { status: 'error', parse_error: `Agent 5 JSON 解析失败：${error.message}`, source_agent: 'agent_5', voiceover_packages: [], total_voiceover_packages: 0 } }];
}

const data = $input.first()?.json || {};
if (data.status === 'error') return [{ json: { ...data, publishing_input_packages: [], selected_count: 0 } }];
function truthy(value) {
  if (value === true || value === 1) return true;
  const normalized = String(value ?? '').trim().toLowerCase();
  return normalized === 'true' || normalized === 'yes' || normalized === '1';
}
const selected = (Array.isArray(data.voiceover_packages) ? data.voiceover_packages : [])
  .filter((pkg) => truthy(pkg.ready_for_agent6))
  .slice(0, 5);
return [{ json: { ...data, status: selected.length > 0 ? 'ready_for_publishing_package' : 'insufficient_data', publishing_input_packages: selected, selected_count: selected.length, selection_note: selected.length > 0 ? '已选择 ready_for_agent6 = true 的内容。' : '没有 ready_for_agent6 = true 的内容，Agent 6 不会生成发布包。' } }];

const data = $input.first()?.json || {};
if (data.status === 'error' || data.status === 'insufficient_data') return [{ json: { ...data, draft_publishing_packages: [] } }];
function text(value) { return String(value ?? '').trim(); }
function cleanTitle(value) {
  const t = text(value).replace(/\s+/g, ' ');
  return t.length > 70 ? `${t.slice(0, 67)}...` : t;
}
function baseKeywords(pkg) {
  const combined = `${pkg.video_title} ${pkg.full_voiceover_script}`.toLowerCase();
  const words = ['wellness', 'healthy habits', 'short video', 'daily routine'];
  if (combined.includes('tea')) words.push('tea routine', 'herbal tea');
  if (combined.includes('rooibos')) words.push('rooibos', 'caffeine free tea');
  if (combined.includes('evening') || combined.includes('night')) words.push('evening routine', 'night routine');
  if (combined.includes('ginger')) words.push('ginger wellness');
  return Array.from(new Set(words)).slice(0, 10);
}
function hashtags(pkg) {
  const keys = baseKeywords(pkg);
  const tags = ['#WellnessTok', '#HealthyHabits', '#Shorts'];
  for (const key of keys) tags.push(`#${key.replace(/\s+/g, '')}`);
  return Array.from(new Set(tags)).slice(0, 8);
}
function buildPackage(pkg, index) {
  const videoTitle = cleanTitle(pkg.video_title);
  const hookLine = text(pkg.full_voiceover_script).split(/[.!?]/).map((x) => x.trim()).filter(Boolean)[0] || videoTitle;
  const tags = hashtags(pkg);
  const seo = baseKeywords(pkg);
  const cta = 'Save this for your next wellness routine and follow for more simple health education.';
  return {
    publishing_id: `agent6_publish_${index + 1}`,
    source_package_id: pkg.package_id,
    video_title: videoTitle,
    cover_text: cleanTitle(videoTitle).slice(0, 34),
    tiktok_caption: `${hookLine}. ${cta}\n\n${tags.slice(0, 5).join(' ')}`,
    instagram_caption: `${hookLine}.\n\n${cta}\n\n${tags.join(' ')}`,
    youtube_shorts_caption: `${videoTitle} — quick wellness education. ${cta} ${tags.slice(0, 4).join(' ')}`,
    cta,
    hashtags: tags,
    seo_keywords: seo,
    suggested_posting_time: { timezone: 'US local time', primary: '7:00 PM', secondary: '12:00 PM', reason: 'Wellness and routine content often fits lunch breaks or evening wind-down behavior.' },
    publishing_checklist: [
      'Confirm final video matches approved script and visuals.',
      'Confirm no high-risk medical promises, medication scenes, or outcome guarantees.',
      'Confirm captions, cover text, hashtags, and CTA are accurate.',
      'Confirm subtitles are readable on mobile.',
      'Confirm product or affiliate disclosure is added if needed.',
      'Confirm human review before posting.'
    ],
    analytics_template: { views: 0, hook_retention_3s: 0, average_watch_time_seconds: 0, completion_rate: 0, saves: 0, shares: 0, comments: 0, profile_visits: 0, link_clicks: 0, follows: 0, notes: '' },
    ab_test_plan: [
      { test_name: 'Hook wording', variant_a: hookLine, variant_b: `A simple wellness routine idea: ${videoTitle}`, success_metric: '3-second retention' },
      { test_name: 'Cover text', variant_a: videoTitle.slice(0, 28), variant_b: 'Try this simple routine', success_metric: 'view-through rate' },
      { test_name: 'CTA', variant_a: 'Save this for later.', variant_b: 'Follow for more simple wellness ideas.', success_metric: 'saves and follows' }
    ],
  };
}
const draftPublishingPackages = (data.publishing_input_packages || []).map(buildPackage);
return [{ json: { ...data, status: 'publishing_package_drafted', draft_publishing_packages: draftPublishingPackages } }];

const data = $input.first()?.json || {};
if (data.status === 'error' || data.status === 'insufficient_data') return [{ json: { ...data, qa_publishing_packages: [] } }];
const riskyTerms = ['cure', 'treat', 'prevent disease', 'replace medication', 'stop medication', 'guaranteed result', 'FDA approved', 'clinically proven', '治愈', '治疗', '替代药物', '停止服药'];
function text(value) { return String(value ?? '').trim(); }
function findRisk(value) { const lower = text(value).toLowerCase(); return riskyTerms.filter((term) => lower.includes(term.toLowerCase())); }
function qaPackage(pkg) {
  const issues = [];
  const corrections = [];
  const fixed = { ...pkg };
  const required = ['tiktok_caption', 'instagram_caption', 'youtube_shorts_caption', 'video_title', 'cover_text', 'cta'];
  for (const field of required) {
    if (!text(fixed[field])) { fixed[field] = field === 'cta' ? 'Save this and follow for more wellness education.' : fixed.video_title || 'Wellness video'; corrections.push(`补充 ${field}。`); }
  }
  if (!Array.isArray(fixed.hashtags) || fixed.hashtags.length < 3) { fixed.hashtags = ['#WellnessTok', '#HealthyHabits', '#Shorts']; corrections.push('补充 Hashtags。'); }
  if (!Array.isArray(fixed.seo_keywords) || fixed.seo_keywords.length < 3) { fixed.seo_keywords = ['wellness', 'healthy habits', 'short video']; corrections.push('补充 SEO Keywords。'); }
  if (!Array.isArray(fixed.publishing_checklist) || fixed.publishing_checklist.length < 3) { fixed.publishing_checklist = ['Confirm script safety.', 'Confirm subtitles.', 'Human review before posting.']; corrections.push('补充 Publishing Checklist。'); }
  if (!fixed.analytics_template || typeof fixed.analytics_template !== 'object') { fixed.analytics_template = { views: 0, saves: 0, shares: 0, comments: 0, notes: '' }; corrections.push('补充 Analytics Template。'); }
  if (!Array.isArray(fixed.ab_test_plan) || fixed.ab_test_plan.length < 2) { fixed.ab_test_plan = [{ test_name: 'Caption hook', variant_a: fixed.tiktok_caption, variant_b: fixed.video_title, success_metric: '3-second retention' }, { test_name: 'CTA', variant_a: 'Save this.', variant_b: 'Follow for more.', success_metric: 'saves and follows' }]; corrections.push('补充 A/B Test Plan。'); }
  if (text(fixed.cover_text).length > 40) { fixed.cover_text = text(fixed.cover_text).slice(0, 37) + '...'; corrections.push('缩短 Cover Text。'); }
  if (text(fixed.tiktok_caption).length > 2200) { fixed.tiktok_caption = text(fixed.tiktok_caption).slice(0, 2197) + '...'; corrections.push('缩短 TikTok Caption。'); }
  const risk = findRisk(JSON.stringify(fixed));
  if (risk.length > 0) issues.push(`发布文案包中出现高风险健康表达：${Array.from(new Set(risk)).join(', ')}。`);
  const qaScore = Math.max(0, 100 - issues.length * 30 - corrections.length * 3 - risk.length * 10);
  const passed = issues.length === 0 && required.every((field) => text(fixed[field])) && fixed.hashtags.length >= 3;
  return { ...fixed, qa_passed: passed, qa_score: qaScore, qa_issues: issues, corrections_made: corrections, ready_for_manual_publish: passed };
}
const qaPublishingPackages = (data.draft_publishing_packages || []).map((pkg) => { try { return qaPackage(pkg); } catch (error) { return { ...pkg, qa_passed: false, qa_score: 0, qa_issues: [`单条发布包 QA 失败：${error.message}`], corrections_made: [], ready_for_manual_publish: false }; } });
return [{ json: { ...data, status: 'qa_complete', qa_publishing_packages: qaPublishingPackages } }];

const data = $input.first()?.json || {};
const generatedAt = new Date().toISOString();
const disclaimer = '本工具仅生成发布文案包、发布检查清单、分析模板和 A/B 测试计划，不自动发布、不自动上传、不购买广告、不自动回复评论，也不构成医疗、法律或平台合规意见。最终发布前仍需人工审核。';
function buildReport(status, packages, parseError) {
  const ready = packages.filter((pkg) => pkg.ready_for_manual_publish);
  const failed = packages.filter((pkg) => !pkg.ready_for_manual_publish);
  const lines = ['# AI Health OS — Agent 6 Publishing Package & Analytics Report', '', '## 一、本次处理结果', '', `- 状态：${status}`, `- 本次处理配音字幕包数量：${packages.length}`, `- 可人工发布：${ready.length}`, `- 未通过 Publishing QA：${failed.length}`];
  if (parseError) lines.push(`- 解析错误：${parseError}`);
  lines.push('', '## 二、可人工发布的内容包', '', ready.length ? ready.map((pkg) => `- ${pkg.video_title}｜QA ${pkg.qa_score} 分｜ready_for_manual_publish = true`).join('\n') : '- 暂无。');
  lines.push('', '## 三、需要人工复核或未通过 QA 的内容', '', failed.length ? failed.map((pkg) => `- ${pkg.video_title}｜问题：${(pkg.qa_issues || []).join('；') || '未通过 QA'}`).join('\n') : '- 暂无。');
  lines.push('', '## 四、逐条发布包', '');
  for (const pkg of packages) {
    lines.push(`### ${pkg.video_title}`, '', `- Cover Text：${pkg.cover_text}`, `- CTA：${pkg.cta}`, `- Suggested Posting Time：${pkg.suggested_posting_time?.primary || ''} / ${pkg.suggested_posting_time?.secondary || ''}`, `- QA：${pkg.qa_passed ? '通过' : '未通过'}（${pkg.qa_score} 分）`, '', '#### TikTok Caption', '', pkg.tiktok_caption || '', '', '#### Instagram Caption', '', pkg.instagram_caption || '', '', '#### YouTube Shorts Caption', '', pkg.youtube_shorts_caption || '', '', `#### Hashtags\n\n${(pkg.hashtags || []).join(' ')}`, '', `#### SEO Keywords\n\n${(pkg.seo_keywords || []).join(', ')}`, '', '#### Publishing Checklist', '');
    for (const item of pkg.publishing_checklist || []) lines.push(`- ${item}`);
    lines.push('', '#### Analytics Template', '', '```json', JSON.stringify(pkg.analytics_template || {}, null, 2), '```', '', '#### A/B Test Plan', '');
    for (const test of pkg.ab_test_plan || []) lines.push(`- ${test.test_name}：A=${test.variant_a}｜B=${test.variant_b}｜指标=${test.success_metric}`);
    lines.push('');
  }
  lines.push('## 五、下一步', '', 'Agent 6 不会自动发布。请人工检查所有 caption、hashtags、SEO、CTA、封面文字和发布检查清单后，再决定是否手动发布。当前不要开发 Agent 7。', '', '## 重要说明', '', disclaimer);
  return lines.join('\n');
}
let status = 'success';
let packages = Array.isArray(data.qa_publishing_packages) ? data.qa_publishing_packages : [];
if (data.status === 'error') status = 'error';
if (data.status === 'insufficient_data') status = 'insufficient_data';
if (status !== 'success') packages = [];
const readyCount = packages.filter((pkg) => pkg.ready_for_manual_publish).length;
const failedCount = packages.filter((pkg) => !pkg.ready_for_manual_publish).length;
const manualReviewCount = packages.filter((pkg) => (pkg.corrections_made || []).length > 0 || (pkg.qa_issues || []).length > 0).length;
return [{ json: { workflow: 'AI Health OS', source_agent: 'agent_5', agent: 'agent_6', version: '1.1', status, generated_at: generatedAt, total_voiceover_packages: packages.length, publishing_packages: packages, handoff: { next_agent: 'manual_publishing_or_future_agent_7', ready_count: readyCount, failed_qa_count: failedCount, manual_review_count: manualReviewCount }, disclaimer, parse_error: data.parse_error || '', report_markdown: buildReport(status, packages, data.parse_error || '') } }];
